package com.bank.slots;

// A pipeline operator with a parallelism and a slot-sharing group name.
class Operator {
    final String name;
    final int parallelism;
    String slotSharingGroup;   // "default" unless isolated

    Operator(String name, int parallelism) {
        this.name = name;
        this.parallelism = parallelism;
        this.slotSharingGroup = "default";
    }

    Operator slotSharingGroup(String group) { this.slotSharingGroup = group; return this; }
}
