package com.bank.slots;

import java.util.ArrayList;
import java.util.List;

// A task slot that can hold one subtask PER distinct operator (within its sharing group).
class Slot {
    final int id;
    final String group;
    final List<String> subtasks = new ArrayList<>();

    Slot(int id, String group) { this.id = id; this.group = group; }

    void place(String subtask) { subtasks.add(subtask); }
}
