package com.bank.slots;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Computes slots needed WITH and WITHOUT slot sharing, and assigns subtasks.
class SlotSharingPlanner {
    private static final Logger log = Logger.getLogger(SlotSharingPlanner.class.getName());

    // Without slot sharing: one slot per subtask = sum of parallelisms.
    int slotsWithoutSharing(List<Operator> operators) {
        int total = operators.stream().mapToInt(o -> o.parallelism).sum();
        log.info(() -> "WITHOUT slot sharing: " + total + " slots (sum of all operator subtasks)");
        return total;
    }

    // With slot sharing: slots needed per group = max parallelism in that group; sum over groups.
    int slotsWithSharing(List<Operator> operators) {
        Map<String, Integer> maxPerGroup = new LinkedHashMap<>();
        for (Operator o : operators) {
            maxPerGroup.merge(o.slotSharingGroup, o.parallelism, Math::max);
        }
        int total = maxPerGroup.values().stream().mapToInt(Integer::intValue).sum();
        log.info(() -> "WITH slot sharing: " + total + " slots (per-group max parallelism: " + maxPerGroup + ")");
        return total;
    }

    // Assign subtasks to slots in the default group: slot i holds one subtask of each operator.
    List<Slot> assignDefaultGroup(List<Operator> operators) {
        int maxP = operators.stream().filter(o -> o.slotSharingGroup.equals("default"))
                .mapToInt(o -> o.parallelism).max().orElse(0);
        List<Slot> slots = new ArrayList<>();
        for (int i = 0; i < maxP; i++) slots.add(new Slot(i, "default"));
        for (Operator o : operators) {
            if (!o.slotSharingGroup.equals("default")) continue;
            for (int p = 0; p < o.parallelism; p++) {
                slots.get(p % maxP).place(o.name + "#" + p); // one subtask of each operator per slot
            }
        }
        for (Slot s : slots) log.info(() -> "Slot " + s.id + " runs a full pipeline slice: " + s.subtasks);
        return slots;
    }

    void verifyFits(int neededSlots, int totalClusterSlots) {
        if (neededSlots > totalClusterSlots) {
            log.severe(() -> "Parallelism needs " + neededSlots + " slots but cluster has only "
                    + totalClusterSlots + " → job cannot be fully deployed (parallelism ≤ total slots)");
        } else {
            log.info(() -> "OK: " + neededSlots + " slots needed ≤ " + totalClusterSlots + " total slots");
        }
    }
}
