package com.bank.slots;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class SlotsDemo {
    private static final Logger log = Logger.getLogger(SlotsDemo.class.getName());

    public static void main(String[] args) {
        SlotSharingPlanner planner = new SlotSharingPlanner();

        // Fraud pipeline: 4 operators, each at parallelism 4.
        List<Operator> ops = new ArrayList<>(List.of(
            new Operator("txn-source", 4),
            new Operator("keyBy-account", 4),
            new Operator("fraud-score", 4),
            new Operator("alert-sink", 4)));

        int clusterSlots = 4; // e.g. 1 TaskManager × 4 slots, or 2×2

        log.info("=== Default slot sharing ===");
        planner.slotsWithoutSharing(ops);     // 16
        int needed = planner.slotsWithSharing(ops); // 4
        planner.verifyFits(needed, clusterSlots);
        planner.assignDefaultGroup(ops);       // each slot = one full pipeline slice

        // The scoring operator is very CPU-heavy → isolate it into its own slot-sharing group.
        log.info("=== Isolate heavy operator into its own group ===");
        ops.get(2).slotSharingGroup("scoring"); // fraud-score now separate
        int neededIsolated = planner.slotsWithSharing(ops); // default max(4) + scoring max(4) = 8
        planner.verifyFits(neededIsolated, clusterSlots);
        log.warning(() -> "Isolation needs more slots (dedicated resources for scoring) — trade-off");
    }
}
